      && verifier.VerifyVectorOfData(tablePos, 28 /*Z_COMBINED*/, 8 /*double*/, false)
      && verifier.VerifyVectorOfData(tablePos, 30 /*Z_PREDICTED*/, 8 /*double*/, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
